pub const ART_REVISION: &str = "wright-art-3";
pub fn frame(pose: &str, tick: usize, looping: bool) -> usize {
    let durations: &[usize] = match pose {
        "idle" => &[9000, 9000, 9000, 9000, 9000, 9000, 9000, 9000],
        "run" => &[6000, 6000, 6000, 6000, 6000, 6000, 6000, 6000],
        "attack" => &[3000, 3000, 3000, 3000, 3000, 3000, 2000, 2000],
        "skill1" => &[2000, 2000, 2000, 3000, 3000, 2000, 2000, 2000],
        "skill2" => &[2000, 2000, 2000, 3000, 3000, 2000, 2000, 2000],
        "skill3" => &[2000, 2000, 2000, 3000, 3000, 2000, 2000, 2000],
        "ult" => &[3000, 3000, 3000, 3000, 3000, 3000, 3000, 3000],
        "hit" => &[1000, 1000, 1000, 1000, 1000, 1000, 1000, 1000],
        "dead" => &[6000, 6000, 6000, 6000, 6000, 6000, 6000, 6000],
        _ => &[9000;8],
    };
    let total: usize=durations.iter().sum();
    let mut elapsed=if looping {tick.saturating_mul(1000)%total}else{tick.saturating_mul(1000).min(total-1)};
    for (i,d) in durations.iter().enumerate(){if elapsed<*d{return i;}elapsed-=d;}
    durations.len()-1
}
